contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint cBalBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;

        bool reverted;
        c.withdraw(_value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint cBalAfter = address(c).balance;
        uint selfBalAfter = address(this).balance;

        assert(
            (!reverted && cBalBefore == cBalAfter + _value && selfBalAfter == selfBalBefore + _value)
            || (reverted && cBalBefore == cBalAfter && selfBalAfter == selfBalBefore)
        );
    }

    receive() external payable {}
}

